import React from "react";

function AttachmentUploader({ items, mode, maxCount, onFilesSelected, onRemoveItem }) {
  if (typeof maxCount === "undefined" || maxCount === null) {
    maxCount = 1;
  }

  const handleFileInputChange = (e) => {
    const selected = e.target.files;
    if (!selected || selected.length === 0) {
      return;
    }
    const currentCount = (items && items.length) || 0;
    if (selected.length + currentCount > maxCount) {
      alert(`최대 ${maxCount}개 까지 입니다.`);
      e.target.value = "";
      return;
    }
    onFilesSelected(selected);
  };

  const handleRemoveClick = (fileId, index) => {
    onRemoveItem(fileId, index);
  };

  return (
    <dl>
      <dt>첨부파일</dt>
      <dd>
        <span className="file_attach">
          {items &&
            items.map((item, index) => (
              <React.Fragment key={item.fileId}>
                <span>{item.fileName}</span>
                {mode === "modify" && (
                  <button
                    className="btn btn_delete"
                    onClick={() => handleRemoveClick(item.fileId, index)}
                  ></button>
                )}
                <br />
              </React.Fragment>
            ))}
          {((items && items.length) || 0) < maxCount && (
            <input
              name="file_0"
              type="file"
              multiple
              onChange={handleFileInputChange}
            />
          )}
        </span>
      </dd>
    </dl>
  );
}

export default AttachmentUploader;

