import React from "react";

interface UploadedFile {
  fileId: string;
  fileName: string;
}

interface AttachmentUploaderProps {
  items?: UploadedFile[];
  mode: "create" | "modify";
  maxCount?: number;
  onFilesSelected: (files: FileList) => void;
  onRemoveItem: (fileId: string, index: number) => void;
}

function AttachmentUploader({
  items,
  mode,
  maxCount,
  onFilesSelected,
  onRemoveItem,
}: AttachmentUploaderProps): JSX.Element {
  if (typeof maxCount === "undefined" || maxCount === null) {
    maxCount = 1;
  }

  const handleFileInputChange = (
    e: React.ChangeEvent<HTMLInputElement>
  ): void => {
    const selected = e.target.files;
    if (!selected || selected.length === 0) {
      return;
    }
    const currentCount = items?.length ?? 0;
    if (selected.length + currentCount > maxCount) {
      alert(`최대 ${maxCount}개 까지 입니다.`);
      e.target.value = "";
      return;
    }
    onFilesSelected(selected);
  };

  const handleRemoveClick = (fileId: string, index: number): void => {
    onRemoveItem(fileId, index);
  };

  return (
    <dl>
      <dt>첨부파일</dt>
      <dd>
        <span className="file_attach">
          {items?.map((item, index) => (
            <React.Fragment key={item.fileId}>
              <span>{item.fileName}</span>
              {mode === "modify" && (
                <button
                  className="btn btn_delete"
                  onClick={() => handleRemoveClick(item.fileId, index)}
                ></button>
              )}
              <br />
            </React.Fragment>
          ))}
          {(items?.length ?? 0) < maxCount && (
            <input
              name="file_0"
              type="file"
              multiple
              onChange={handleFileInputChange}
            />
          )}
        </span>
      </dd>
    </dl>
  );
}

export default AttachmentUploader;

